const { commandFactory, itemType, getState } = options;

const { selectedRows } = getState().grid;
if (selectedRows.length !== 1) {
	return { disabled: true };
}

const selectedItemId = selectedRows[0];
const relationshipItem = window.grid._grid.rows.get(selectedItemId);
const commandAlias = target['command_alias@keyed_name'];
const openCommand = commandFactory(commandAlias, {
	item: relationshipItem,
	itemType
});

return {
	disabled: !openCommand.canExecute()
};
